void appendEntry(Path zip, String name, String content) throws IOException {
    Map<String,byte[]> wszystkie = new LinkedHashMap<>();
    try (ZipInputStream zis = new ZipInputStream(Files.newInputStream(zip))) {
        ZipEntry e;
        while ((e = zis.getNextEntry()) != null) { wszystkie.put(e.getName(), zis.readAllBytes()); zis.closeEntry(); }
    }
    wszystkie.put(name, content.getBytes());
    try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(zip))) {
        for (var e : wszystkie.entrySet()) { zos.putNextEntry(new ZipEntry(e.getKey())); zos.write(e.getValue()); zos.closeEntry(); }
    }
}

