void unzip(Path zipFile, Path targetDir) throws IOException {
    try (ZipInputStream zis = new ZipInputStream(Files.newInputStream(zipFile))) {
        ZipEntry e;
        while ((e = zis.getNextEntry()) != null) {
            Path docelowy = targetDir.resolve(e.getName()).normalize();
            if (!docelowy.startsWith(targetDir.normalize())) throw new SecurityException("Zip Slip: " + e.getName());
            Files.createDirectories(docelowy.getParent());
            Files.write(docelowy, zis.readAllBytes());
            zis.closeEntry();
        }
    }
}

